        "fiches listées différentes": { en: "distinct listed records", de: "verschiedene gelistete Datensätze", es: "fichas listadas distintas", zh: "条不同的列名记录", ar: "سجلات مدرجة مختلفة" },
        "Sélectionner le groupe": { en: "Select the group", de: "Gruppe auswählen", es: "Seleccionar el grupo", zh: "选择该组", ar: "حدد المجموعة" },
        "alertes sans regroupement": { en: "ungrouped alerts", de: "Alarme ohne Gruppe", es: "alertas sin agrupar", zh: "条未分组警报", ar: "تنبيهات غير مجمّعة" },
        "alerte(s) écartée(s) de l'action en masse :": { en: "alert(s) set aside from the bulk action:", de: "Alarm(e) von der Massenaktion ausgenommen:", es: "alerta(s) descartada(s) de la acción masiva:", zh: "条警报未纳入批量操作：", ar: "تنبيه استُبعد من الإجراء الجماعي:" },
        "Fermer le compte rendu": { en: "Close the report", de: "Bericht schließen", es: "Cerrar el informe", zh: "关闭报告", ar: "أغلق التقرير" },
        "Alerte introuvable.": { en: "Alert not found.", de: "Alarm nicht gefunden.", es: "Alerta no encontrada.", zh: "未找到警报。", ar: "التنبيه غير موجود." },
        "Alerte déjà close.": { en: "Alert already closed.", de: "Alarm bereits geschlossen.", es: "Alerta ya cerrada.", zh: "警报已关闭。", ar: "التنبيه مغلق بالفعل." },
        "Liste de gel (périmètre SANCTION) : priorité sous le plancher.": { en: "Freeze list (SANCTION perimeter): priority below the floor.", de: "Einfrierungsliste (Perimeter SANCTION): Priorität unter der Untergrenze.", es: "Lista de congelación (perímetro SANCTION): prioridad por debajo del mínimo.", zh: "冻结名单（SANCTION 范围）：优先级低于下限。", ar: "قائمة تجميد (نطاق SANCTION): أولوية دون الحد الأدنى." },
        "Une décision est déjà en attente de validation.": { en: "A decision is already awaiting validation.", de: "Eine Entscheidung wartet bereits auf Freigabe.", es: "Ya hay una decisión pendiente de validación.", zh: "已有一项决定在等待复核。", ar: "هناك قرار بانتظار الاعتماد بالفعل." },
        "Assignée à un autre analyste : c'est à son assigné de la proposer.": { en: "Assigned to another analyst: it is for its assignee to propose it.", de: "Einem anderen Analysten zugewiesen: der Zugewiesene schlägt die Entscheidung vor.", es: "Asignada a otro analista: le corresponde a su asignado proponerla.", zh: "已指派给其他分析员：应由其负责人提议。", ar: "مسندة إلى محلل آخر: على المسند إليه أن يقترحها." },
        "Liste de gel (périmètre SANCTION) : sans validation 4-yeux, la proposer en masse la clôturerait sans second regard. À instruire à l'unité.": { en: "Freeze list (SANCTION perimeter): without four-eyes validation, proposing it in bulk would close it with no second look. Investigate it individually.", de: "Einfrierungsliste (Perimeter SANCTION): ohne Vier-Augen-Freigabe würde ein Massenvorschlag sie ohne zweiten Blick schließen. Einzeln bearbeiten.", es: "Lista de congelación (perímetro SANCTION): sin validación a cuatro ojos, proponerla en masa la cerraría sin una segunda mirada. Instrúyala individualmente.", zh: "冻结名单（SANCTION 范围）：未启用四眼复核时，批量提议会在无人复查的情况下将其关闭。请逐条调查。", ar: "قائمة تجميد (نطاق SANCTION): دون تحقق الأربع أعين، سيؤدي اقتراحها جماعيًا إلى إغلاقها دون نظرة ثانية. حقّق فيها على حدة." },
        "Proposer « faux positif » pour la sélection": { en: "Propose “false positive” for the selection", de: "„Fehlalarm“ für die Auswahl vorschlagen", es: "Proponer «falso positivo» para la selección", zh: "为所选警报提议“误报”", ar: "اقترح «إيجابي كاذب» للتنبيهات المحددة" },
        "Proposer « vrai positif » pour la sélection": { en: "Propose “true positive” for the selection", de: "„Echter Treffer“ für die Auswahl vorschlagen", es: "Proponer «verdadero positivo» para la selección", zh: "为所选警报提议“真阳性”", ar: "اقترح «إيجابي حقيقي» للتنبيهات المحددة" },
        "Un même motif pour chaque alerte sélectionnée : chacune reçoit sa proposition, et chacune sera validée une par une (4-yeux) par un réviseur différent de vous.": { en: "One reason for every selected alert: each receives its own proposal, and each will be validated one by one (four-eyes) by a reviewer other than you.", de: "Eine Begründung für jeden ausgewählten Alarm: jeder erhält seinen eigenen Vorschlag, und jeder wird einzeln (Vier-Augen) von einem anderen Prüfer als Ihnen freigegeben.", es: "Un mismo motivo para cada alerta seleccionada: cada una recibe su propuesta, y cada una será validada una a una (cuatro ojos) por un revisor distinto de usted.", zh: "所选每条警报使用同一理由：每条都会收到各自的提议，并由您以外的复核员逐条复核（四眼）。", ar: "سبب واحد لكل تنبيه محدد: يتلقى كل تنبيه اقتراحه، وسيُعتمد كل منها على حدة (أربع أعين) من قِبل مراجع غيرك." },
        "Motivation réglementaire commune...": { en: "Common regulatory justification...", de: "Gemeinsame regulatorische Begründung...", es: "Motivación reglamentaria común...", zh: "共同的监管理由……", ar: "مبرر تنظيمي مشترك..." },
        "Faux positif sur une liste de gel (périmètre SANCTION)": { en: "False positive on a freeze list (SANCTION perimeter)", de: "Fehlalarm auf einer Einfrierungsliste (Perimeter SANCTION)", es: "Falso positivo en una lista de congelación (perímetro SANCTION)", zh: "冻结名单上的误报（SANCTION 范围）", ar: "إيجابي كاذب على قائمة تجميد (نطاق SANCTION)" },
        "Je confirme : chacune a été instruite": { en: "I confirm: each one was investigated", de: "Ich bestätige: jeder wurde bearbeitet", es: "Confirmo: cada una ha sido instruida", zh: "我确认：每条都已调查", ar: "أؤكد: تم التحقيق في كل منها" },
