        "paire(s) à réexaminer": { en: "pair(s) to review", de: "Paar(e) zu überprüfen", es: "par(es) por reexaminar", zh: "个待复核的配对", ar: "زوج (أزواج) للمراجعة" },
        "Tous les états": { en: "All states", de: "Alle Status", es: "Todos los estados", zh: "所有状态", ar: "كل الحالات" },
        "Reconduire": { en: "Renew", de: "Verlängern", es: "Renovar", zh: "续期", ar: "تجديد" },
        "Reconduire la paire de liste blanche": { en: "Renew the whitelist pair", de: "Whitelist-Paar verlängern", es: "Renovar el par de la lista blanca", zh: "续期白名单配对", ar: "تجديد زوج القائمة البيضاء" },
        "Vous avez examiné ce qui a changé (événement WHITELIST_STALE de l'alerte) et le faux positif demeure. Motif obligatoire : la paire couvrira la fiche et le client tels qu'ils ont été criblés en dernier.": { en: "You have reviewed what changed (the alert's WHITELIST_STALE event) and the false positive stands. A reason is required: the pair will cover the record and the client as they were last screened.", de: "Sie haben geprüft, was sich geändert hat (Ereignis WHITELIST_STALE des Alarms), und der Fehlalarm bleibt bestehen. Begründung erforderlich: Das Paar deckt den Datensatz und den Kunden so ab, wie sie zuletzt geprüft wurden.", es: "Ha examinado lo que ha cambiado (evento WHITELIST_STALE de la alerta) y el falso positivo se mantiene. Motivo obligatorio: el par cubrirá la ficha y el cliente tal como se cribaron por última vez.", zh: "您已审查变更内容（警报的 WHITELIST_STALE 事件），误报结论不变。必须填写理由：该配对将覆盖最近一次筛查时的名单记录和客户。", ar: "لقد راجعتَ ما تغيّر (حدث WHITELIST_STALE في التنبيه) وما زالت النتيجة إيجابية كاذبة. السبب إلزامي: سيغطي الزوج السجل والعميل كما فُحصا آخر مرة." },
        "Motif du maintien en liste blanche...": { en: "Reason for keeping the pair whitelisted...", de: "Begründung für den Verbleib auf der Whitelist...", es: "Motivo del mantenimiento en la lista blanca...", zh: "保留在白名单中的理由……", ar: "سبب الإبقاء في القائمة البيضاء..." },
        "Liste blanche reconduite": { en: "Whitelist pair renewed", de: "Whitelist-Paar verlängert", es: "Par de lista blanca renovado", zh: "白名单配对已续期", ar: "تم تجديد زوج القائمة البيضاء" },
        "la fiche listée a changé depuis la décision": { en: "the listed record has changed since the decision", de: "der gelistete Datensatz hat sich seit der Entscheidung geändert", es: "la ficha listada ha cambiado desde la decisión", zh: "自决定以来名单记录已变更", ar: "تغيّر السجل المدرج منذ القرار" },
        "l'identification du client a changé depuis la décision": { en: "the client's identification has changed since the decision", de: "die Identifikation des Kunden hat sich seit der Entscheidung geändert", es: "la identificación del cliente ha cambiado desde la decisión", zh: "自决定以来客户身份信息已变更", ar: "تغيّرت بيانات تعريف العميل منذ القرار" },
        "la fiche listée et l'identification du client ont changé depuis la décision": { en: "the listed record and the client's identification have changed since the decision", de: "der gelistete Datensatz und die Identifikation des Kunden haben sich seit der Entscheidung geändert", es: "la ficha listada y la identificación del cliente han cambiado desde la decisión", zh: "自决定以来名单记录和客户身份信息均已变更", ar: "تغيّر السجل المدرج وبيانات تعريف العميل منذ القرار" },
        "paire antérieure au suivi : rien n'établit ce que sa décision couvrait": { en: "pair predates tracking: nothing establishes what its decision covered", de: "Paar älter als die Nachverfolgung: nichts belegt, was seine Entscheidung abdeckte", es: "par anterior al seguimiento: nada establece lo que cubría su decisión", zh: "该配对早于跟踪机制：无法确定其决定所覆盖的内容", ar: "زوج سابق للتتبع: لا شيء يثبت ما كان قراره يغطيه" },
