        "Dernier passage en échec :": { en: "Last pass failed:", de: "Letzter Durchlauf fehlgeschlagen:", es: "Última pasada fallida:", zh: "最近一次批次失败：", ar: "آخر دفعة فشلت:" },
        "Passage en cours :": { en: "Pass in progress:", de: "Durchlauf läuft:", es: "Pasada en curso:", zh: "批次进行中：", ar: "دفعة جارية:" },
