        "Re-criblage après mise à jour de liste": { en: "Re-screening after a list update", de: "Rescreening nach Listenaktualisierung", es: "Recribado tras actualización de lista", zh: "名单更新后的复筛", ar: "إعادة الفحص بعد تحديث قائمة" },
        "Criblage des clients nouveaux ou modifiés": { en: "Screening of new or modified clients", de: "Screening neuer oder geänderter Kunden", es: "Cribado de los clientes nuevos o modificados", zh: "新增或变更客户的筛查", ar: "فحص العملاء الجدد أو المعدَّلين" },
